// a^b mod m dla |a| <= 1e18, 0 <= b <= 1e18, 1 <= m <= 1e18 (mnożenie przez __int128).
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

ll powmod(ll a, ll b, ll m) {
    a %= m;
    if (a < 0) a += m;                    // podstawa ujemna -> reszta nieujemna
    ll r = 1 % m;                         // 1 % m: dla m = 1 wynik ma być 0
    while (b > 0) {
        if (b & 1) r = (__int128)r * a % m;   // bit wykładnika = 1 -> domnażamy
        a = (__int128)a * a % m;              // a, a^2, a^4, a^8, ...
        b >>= 1;
    }
    return r;
}

int main() {
    ll a, b, m;
    cin >> a >> b >> m;
    cout << powmod(a, b, m) << "\n";
}

// Wersja rekurencyjna — bezpośrednio ze wzoru a^b = (a^(b/2))^2 * a^(b mod 2).
const long long MOD = 1'000'000'007;
long long pw(long long a, long long b) {
    if (b == 0) return 1;
    long long h = pw(a, b / 2);
    long long r = h * h % MOD;
    if (b % 2 == 1) r = r * (a % MOD) % MOD;
    return r;
}

