// Odwrotność a modulo m (dowolne m >= 2) przez rozszerzony Euklides; "BRAK", gdy gcd(a, m) != 1.
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

ll extgcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) { x = 1; y = 0; return a; }
    ll x1, y1, g = extgcd(b, a % b, x1, y1);
    x = y1; y = x1 - (a / b) * y1;
    return g;
}

ll modInverse(ll a, ll m) {                 // -1, gdy odwrotność nie istnieje
    a %= m; if (a < 0) a += m;
    ll x, y;
    if (extgcd(a, m, x, y) != 1) return -1;
    x %= m; if (x < 0) x += m;
    return x;
}

int main() {
    ll a, m;
    cin >> a >> m;
    ll r = modInverse(a, m);
    if (r == -1) cout << "BRAK\n";
    else cout << r << "\n";
}

// Odwrotność modulo liczba pierwsza z małego twierdzenia Fermata: a^(p-2).
const long long MOD = 1'000'000'007;
long long power(long long a, long long b) {
    long long r = 1; a %= MOD; if (a < 0) a += MOD;
    while (b) { if (b & 1) r = r * a % MOD; a = a * a % MOD; b >>= 1; }
    return r;
}
long long inv(long long a) { return power(a, MOD - 2); }   // wymaga a % MOD != 0

// Odwrotności wszystkich liczb 1..n modulo p w O(n).
// Z p = q*i + r (q = p / i, r = p % i):  0 ≡ q*i + r  =>  i^(-1) ≡ -q * r^(-1)  (mod p).
const long long MOD = 1'000'000'007;
vector<long long> inverses(int n) {
    vector<long long> inv(n + 1);
    inv[1] = 1;
    for (int i = 2; i <= n; i++)
        inv[i] = (MOD - MOD / i) * inv[MOD % i] % MOD;
    return inv;
}

