// q zapytań C(n, k) mod 1e9+7, n <= 1e6. Preprocessing silni i odwrotności silni.
#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1'000'000'007;
const int MAXN = 1'000'000;
long long fact[MAXN + 1], invfact[MAXN + 1];

long long power(long long a, long long b) {
    long long r = 1; a %= MOD;
    while (b) { if (b & 1) r = r * a % MOD; a = a * a % MOD; b >>= 1; }
    return r;
}

void init() {
    fact[0] = 1;
    for (int i = 1; i <= MAXN; i++) fact[i] = fact[i - 1] * i % MOD;
    invfact[MAXN] = power(fact[MAXN], MOD - 2);              // jedna odwrotność (Fermat)
    for (int i = MAXN; i > 0; i--) invfact[i - 1] = invfact[i] * i % MOD;
}

long long C(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD;
}

int main() {
    init();
    int q;
    cin >> q;
    while (q--) {
        int n, k;
        cin >> n >> k;
        cout << C(n, k) << "\n";
    }
}

// Trójkąt Pascala: dowolny moduł (także złożony), n <= ~5000. O(n^2) czasu i pamięci.
const int N = 1000;
long long Cp[N + 1][N + 1];
void pascal(long long mod) {
    for (int n = 0; n <= N; n++) {
        Cp[n][0] = Cp[n][n] = 1 % mod;
        for (int k = 1; k < n; k++) Cp[n][k] = (Cp[n - 1][k - 1] + Cp[n - 1][k]) % mod;
    }
}

// Twierdzenie Lucasa: C(n, k) mod p = iloczyn C(n_i, k_i) po cyfrach n, k w systemie o podstawie p.
// p pierwsze i małe (silnie do p - 1), n, k do 1e18.
long long lucasP;
vector<long long> lf, lif;                 // silnie i odwrotności silni modulo p
long long pmod(long long a, long long b, long long m) {
    long long r = 1; a %= m;
    while (b) { if (b & 1) r = r * a % m; a = a * a % m; b >>= 1; }
    return r;
}
void lucasInit(long long p) {
    lucasP = p;
    lf.assign(p, 1); lif.assign(p, 1);
    for (long long i = 1; i < p; i++) lf[i] = lf[i - 1] * i % p;
    lif[p - 1] = pmod(lf[p - 1], p - 2, p);
    for (long long i = p - 1; i > 0; i--) lif[i - 1] = lif[i] * i % p;
}
long long smallC(long long n, long long k) {     // n, k < p
    if (k < 0 || k > n) return 0;
    return lf[n] * lif[k] % lucasP * lif[n - k] % lucasP;
}
long long lucas(long long n, long long k) {
    long long r = 1;
    while (n > 0 || k > 0) {
        r = r * smallC(n % lucasP, k % lucasP) % lucasP;
        if (r == 0) return 0;
        n /= lucasP; k /= lucasP;
    }
    return r;
}

