// F(n) mod 1e9+7 dla n <= 1e18 przez potęgowanie macierzy 2x2.
#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1'000'000'007;
typedef array<array<long long, 2>, 2> Mat;

Mat mul(const Mat &A, const Mat &B) {
    Mat C{};                                     // zera
    for (int i = 0; i < 2; i++)
        for (int k = 0; k < 2; k++)
            for (int j = 0; j < 2; j++)
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
    return C;
}

Mat mpow(Mat A, long long e) {
    Mat R{};
    R[0][0] = R[1][1] = 1;                       // macierz jednostkowa
    while (e > 0) {
        if (e & 1) R = mul(R, A);
        A = mul(A, A);
        e >>= 1;
    }
    return R;
}

int main() {
    long long n;
    cin >> n;
    Mat M{};
    M[0][0] = 1; M[0][1] = 1; M[1][0] = 1;       // [[1,1],[1,0]]
    cout << mpow(M, n)[0][1] << "\n";            // element [0][1] = F(n)
}

// Ogólna rekurencja liniowa rzędu k: f(n) = c1 f(n-1) + ... + ck f(n-k)  (mod 1e9+7).
// Wejście: k, potem c1..ck, potem f(0)..f(k-1), potem n (do 1e18).
#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1'000'000'007;
typedef vector<vector<long long>> Mat;

Mat mul(const Mat &A, const Mat &B) {
    int n = A.size();
    Mat C(n, vector<long long>(n, 0));
    for (int i = 0; i < n; i++)
        for (int k = 0; k < n; k++) {
            if (A[i][k] == 0) continue;
            for (int j = 0; j < n; j++)
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
        }
    return C;
}

Mat mpow(Mat A, long long e) {
    int n = A.size();
    Mat R(n, vector<long long>(n, 0));
    for (int i = 0; i < n; i++) R[i][i] = 1;
    for (; e > 0; e >>= 1) {
        if (e & 1) R = mul(R, A);
        A = mul(A, A);
    }
    return R;
}

int main() {
    int k;
    cin >> k;
    vector<long long> c(k), f(k);
    for (auto &x : c) cin >> x;
    for (auto &x : f) cin >> x;
    long long n;
    cin >> n;
    Mat M(k, vector<long long>(k, 0));
    for (int j = 0; j < k; j++) M[0][j] = (c[j] % MOD + MOD) % MOD;   // pierwszy wiersz: współczynniki
    for (int i = 1; i < k; i++) M[i][i - 1] = 1;                     // przesunięcie stanu
    // v0 = (f(k-1), ..., f(0)); f(n) = ostatnia współrzędna M^n * v0
    Mat P = mpow(M, n);
    long long ans = 0;
    for (int j = 0; j < k; j++) ans = (ans + P[k - 1][j] * (f[k - 1 - j] % MOD)) % MOD;
    cout << ans << "\n";
}

